sys_script_include.script:
var PasRecordGuard = Class.create();

PasRecordGuard.INTEGRATION_ROLE = 'x_gegis_ins_policy.integration_user';

PasRecordGuard.prototype = {

    initialize: function () {},

    // When the policy administration system is the system of record, policy /
    // term / version rows are read-only copies: people cannot edit them,
    // integrations and system jobs keep them in step.
    guard: function (current) {
        if (current.getValue('system_of_record') !== Constants.CHOICE.SYSTEM_OF_RECORD.EXTERNAL)
            return;
        if (current.system_of_record.changes())
            return;   // switching the system of record itself is allowed
        if (!gs.isInteractive() || gs.hasRole(PasRecordGuard.INTEGRATION_ROLE))
            return;
        current.setAbortAction(true);
        gs.addErrorMessage(gs.getMessage('This record is managed by the policy administration system. Change it there; the next sync updates Policy Suite.'));
    },

    type: 'PasRecordGuard'
};
